        if (s.rules.stacking) stackOn(s, victim, 7, 'W4', tp, fx);
        else { hitWithDraw(s, victim, 7, fx, tp, 'W4'); s._skip = true; }
        fx.push({ t: 'mais7', pid: tp, target: victim });
