  function debugGive(s, pid, tk) {
    const H = s.hands, mine = H[pid]; if (!mine) return false;
    if (s.apocUsed && s.replaced[tk] && s.replaced[tk].effect === 'apocalipse') return false;
    const ids = DECK.filter(d => !d.ph && typeKey(d) === tk).map(d => d.id);
    if (ids.some(id => mine.indexOf(id) >= 0)) return true;          // já tem
    const top = s.discard[s.discard.length - 1];
    let id = ids.find(x => s.deck.indexOf(x) >= 0);
    const give = mine.length ? mine[rnd(mine.length)] : null;
    if (id !== undefined) { s.deck.splice(s.deck.indexOf(id), 1); if (give !== null) { mine.splice(mine.indexOf(give), 1); s.deck.push(give); s.deck = shuffle(s.deck); } mine.push(id); return true; }
    const owner = s.order.find(q => q !== pid && ids.some(x => H[q].indexOf(x) >= 0));
    if (owner) { id = ids.find(x => H[owner].indexOf(x) >= 0); H[owner].splice(H[owner].indexOf(id), 1); if (give !== null) { mine.splice(mine.indexOf(give), 1); H[owner].push(give); } mine.push(id); return true; }
    id = ids.find(x => x !== top && s.discard.indexOf(x) >= 0);
    if (id !== undefined) { s.discard.splice(s.discard.indexOf(id), 1); if (give !== null) { mine.splice(mine.indexOf(give), 1); s.discard.splice(Math.max(0, s.discard.length - 1), 0, give); } mine.push(id); return true; }
    return false;
  }
  function botTarget(s, pid) {
    return s.order.filter(p => p !== pid && !(s.boss && pid === s.boss.worker && p === s.boss.boss)).sort((a, b) => s.hands[a].length - s.hands[b].length)[0];
  }
  function botMove(s, pid) {
    const hand = s.hands[pid];
    const mk = id => {
      const c = DECK[id];
      if (effOf(s, id) === 'vampira') { const as = s.stack ? 'W4' : 'W4'; return { type: 'play', pid, card: id, as, color: bestColor(hand, id), uno: hand.length === 2 ? true : undefined }; }
      if (effOf(s, id) === 'buraco') { const o = holeOptions(s).filter(tk => canPlayType(s, tk)); const as = o.find(tk => !/7$/.test(tk)) || o[0]; return { type: 'play', pid, card: id, as, color: bestColor(hand, id), target: botTarget(s, pid), uno: hand.length === 2 ? true : undefined }; }
      return { type: 'play', pid, card: id, color: c.c === 'k' ? bestColor(hand, id) : undefined,
               target: (s.rules && s.rules.sevenZero && c.v === '7') ? botTarget(s, pid) : undefined, uno: hand.length === 2 ? true : undefined };
    };
    if (s.drawing === pid) return { type: 'draw', pid };
    if (s.drawn && s.drawn.pid === pid) return mk(s.drawn.card);
    const ok = hand.filter(id => canPlay(s, id));
    if (!ok.length) return { type: 'draw', pid };
    const nextHand = s.hands[s.order[nextIdx(s, s.turn, 1)]].length;
    const minOther = Math.min.apply(null, s.order.filter(p => p !== pid).map(p => s.hands[p].length));
    const score = id => {
      const c = DECK[id];
      if (c.c === 'k') return nextHand <= 2 ? 50 : (c.v === 'W4' ? 1 : 2);
      if (s.rules && s.rules.sevenZero && c.v === '7') return minOther < hand.length - 1 ? 70 : 5;
      if (/^[0-9]$/.test(c.v)) return 20 + (+c.v);
      return nextHand <= 2 ? 60 : 30;
    };
    ok.sort((a, b) => score(b) - score(a));
    return mk(ok[0]);
  }
  function bestColor(hand, except) {
    const cnt = { r: 0, y: 0, g: 0, b: 0 };
    for (const id of hand) if (id !== except && DECK[id].c !== 'k') cnt[DECK[id].c]++;
    let best = COLORS[rnd(4)], m = 0;
    for (const c of COLORS) if (cnt[c] > m) { m = cnt[c]; best = c; }
    return best;
  }

  /* ---------- 7. Substituição por comentário de inscrito ---------- */
  const availableTypes = s => TYPE_KEYS.filter(k => !s.replaced[k]);
  const swapDueAt = (s, st) => { const S2 = Object.assign({}, DEFAULT_SETTINGS, st); return (s.swapBase || 0) + (s.repMode ? S2.swapRepeatSec : S2.swapIntervalSec) * 1000; };
  const activeComments = comments => arr(comments).filter(c => c && c.id && !c.off);
  // 1ª rodada: cada comentário ativo uma vez (sorteado). Acabou? repete (sorteado de novo) até todas as 52 cartas virarem.
  function nextComment(s, comments, order) {
    const act = activeComments(comments);
    if (!act.length) return null;
    const avail = act.filter(c => s.used.indexOf(c.id) < 0);
    if (avail.length) return order === 'random' ? avail[rnd(avail.length)] : avail[0];
    const noAp = act.filter(c => c.effect !== 'apocalipse');       // o Apocalipse só existe uma vez
    if (!noAp.length) return null;
    let pool = act.filter(c => arr(s.rep).indexOf(c.id) < 0);
    if (!pool.length) pool = act;                 // já repetiu todos: começa outra volta
    let c = pool[rnd(pool.length)], apSub = false;
    let apId = null;
    if (c.effect === 'apocalipse') { apId = c.id; const alt = pool.filter(x => x.effect !== 'apocalipse'); c = (alt.length ? alt : noAp)[rnd((alt.length ? alt : noAp).length)]; apSub = true; }
    return Object.assign({}, c, { _rep: true, _apSub: apSub, _apId: apId });
  }
  const firstRoundDone = (s, comments) => { const act = activeComments(comments); return act.length > 0 && act.every(c => s.used.indexOf(c.id) >= 0); };
  function resizeCover(file, w, h) {           // imagem de fundo da carta (proporção da carta)
    return new Promise((res, rej) => {
      const fr = new FileReader();
      fr.onerror = () => rej(new Error('Não foi possível ler a imagem'));
      fr.onload = () => { const img = new Image(); img.onerror = () => rej(new Error('Arquivo de imagem inválido'));
        img.onload = () => { const c = document.createElement('canvas'); c.width = w; c.height = h; const x = c.getContext('2d');
          const s = Math.max(w / img.width, h / img.height); x.drawImage(img, (w - img.width * s) / 2, (h - img.height * s) / 2, img.width * s, img.height * s);
          res(c.toDataURL('image/jpeg', 0.72)); };
        img.src = fr.result; };
      fr.readAsDataURL(file);
    });
  }
  function commentSnapshot(c) {
    // a foto fica só na config (economiza banda); o resto vai junto no estado
    return { id: c.id, author: c.author || '@inscrito', text: c.text || '', emoji: c.emoji || '⭐',
             a: c.a || '#FF6FB5', b: c.b || '#7B2FF7', pattern: c.pattern || 'dots',
             effect: EFFECTS[c.effect] ? c.effect : 'turbo',
             bgZ: +c.bgZ || 1, bgX: +c.bgX || 0, bgY: +c.bgY || 0, hasBg: !!c.bg };
  }
  function startSwap(s, comment, now) {
    const cands = availableTypes(s);
    if (!cands.length || !comment) return false;
    const target = cands[rnd(cands.length)];
    const reel = [];
    const pool = shuffle(TYPE_KEYS.slice());      // enfeites da roleta: todos os tipos, bem embaralhados
    for (let i = 0; i < 40; i++) reel.push(pool[i % pool.length]);
    for (let i = 1; i < 40; i++) if (reel[i] === reel[i - 1]) reel[i] = pool[(i * 7) % pool.length];
    const stop = 32;
    reel[stop] = target;
    s.seq++;
    s.adminSwap = false;
    const isRep = !!comment._rep;
    if (isRep) s.repMode = true;
    s.swap = { id: s.seq, phase: 'announce', t: now, t0: now, comment: commentSnapshot(comment), target, reel, stop, rep: isRep, apSub: !!comment._apSub, apId: comment._apId || null,
      cands: cands.length <= 10 ? shuffle(cands.slice()) : null, last: cands.length === 1 };
    s.fx = { seq: s.seq, items: [{ t: 'swapStart' }] };
    return true;
  }
  function phaseDuration(phase, st, sw) {
    st = Object.assign({}, DEFAULT_SETTINGS, st);
    if (sw && sw.rep) return phase === 'announce' ? 1300 : phase === 'reveal' ? 4600 : 0;
    if (phase === 'announce') return 2600;
    if (phase === 'comment') return st.highlightSec * 1000 + 700;
    if (phase === 'roulette') return st.rouletteSec * 1000 + 3200;
    if (phase === 'reveal') return 6200;
    return 0;
  }
  const PHASES = ['announce', 'comment', 'roulette', 'reveal'];
  function tickSwap(s, now, st) {
    const sw = s.swap;
    if (!sw) return false;
    if (now < sw.t + phaseDuration(sw.phase, st, sw)) return false;
    const i = PHASES.indexOf(sw.phase);
    if (i < PHASES.length - 1) {
      sw.phase = sw.rep && sw.phase === 'announce' ? 'reveal' : PHASES[i + 1]; sw.t = now;
    } else {
      s.replaced[sw.target] = sw.comment;
      if (sw.rep) { s.rep = arr(s.rep); if (s.rep.indexOf(sw.comment.id) >= 0) s.rep = []; s.rep.push(sw.comment.id); if (sw.apId && s.rep.indexOf(sw.apId) < 0) s.rep.push(sw.apId); }   // uma volta de repetidas fechou: começa outra
      else s.used.push(sw.comment.id);
      s.lastComment = { comment: sw.comment, target: sw.target };
      const paused = now - (sw.t0 || now);
      if (s.quick) s.quick.until += paused;
      if (s.pend) s.pend.until += paused;
      if (s.zwDue) s.zwDue.until += paused;
      if (s.spec && s.spec.until) s.spec.until += paused;
      if (s.unoDue) s.unoDue.until += paused;
      s.swap = null;
      s.swapBase = now;
      s.seq++;
      s.fx = { seq: s.seq, items: [{ t: 'swapDone', target: sw.target }] };
      if (s.apocUsed) apocSweep(s, s.fx.items);   // novo Apocalipse no meio da rodada: já foi usado, então não existe
    }
    return true;
  }

  /* ---------- 8. Desenho das cartas (canvas) ---------- */
  const CW = 320, CH = 500;
  const INK = '#10202B';
  const FONT_D = '"Lilita One", "Arial Black", sans-serif';
  const FONT_B = 'Nunito, "Segoe UI", sans-serif';
  const FONT_E = '"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif';

  function mkCanvas(target) {
    const c = target || document.createElement('canvas');
    c.width = CW; c.height = CH;
    return c;
  }
  function rr(ctx, x, y, w, h, r) {
    ctx.beginPath(); ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();
  }
  function hexPath(ctx, cx, cy, r, rot) {
    rot = rot === undefined ? -Math.PI / 2 : rot;
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = rot + Math.PI / 3 * i;
      const x = cx + r * Math.cos(a), y = cy + r * Math.sin(a);
      if (i) ctx.lineTo(x, y); else ctx.moveTo(x, y);
    }
    ctx.closePath();
  }
  function strokeFillText(ctx, t, x, y, fill, stroke, lw) {
    if (lw) { ctx.lineWidth = lw; ctx.strokeStyle = stroke; ctx.lineJoin = 'round'; ctx.strokeText(t, x, y); }
    ctx.fillStyle = fill; ctx.fillText(t, x, y);
  }
  function quadHex(ctx, x, y, r, lw) {
    ctx.save();
    hexPath(ctx, x, y, r); ctx.clip();
    const q = [['r', -1, -1], ['b', 1, -1], ['y', -1, 1], ['g', 1, 1]];
    for (const [c, sx, sy] of q) { ctx.fillStyle = COLOR_HEX[c]; ctx.fillRect(x + (sx < 0 ? -r : 0), y + (sy < 0 ? -r : 0), r, r); }
    ctx.restore();
    if (lw) { hexPath(ctx, x, y, r); ctx.lineWidth = lw; ctx.strokeStyle = INK; ctx.stroke(); }
  }
  function arrow(ctx, x0, y0, x1, y1, w, color, outline) {
    const ang = Math.atan2(y1 - y0, x1 - x0), hl = w * 1.5;
    const bx = x1 - Math.cos(ang) * hl * 0.8, by = y1 - Math.sin(ang) * hl * 0.8;
    const pass = (col, extra) => {
      ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
      ctx.lineWidth = w + extra; ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(bx, by); ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(bx + Math.cos(ang + Math.PI / 2) * hl, by + Math.sin(ang + Math.PI / 2) * hl);
      ctx.lineTo(bx + Math.cos(ang - Math.PI / 2) * hl, by + Math.sin(ang - Math.PI / 2) * hl);
      ctx.closePath(); ctx.lineWidth = extra || 0.01; ctx.fill(); if (extra) ctx.stroke();
    };
    if (outline) pass(INK, outline * 2);
    pass(color, 0);
  }
  // desenha o símbolo do valor (número, bloqueio, inverter, +2, coringa, +4)
  function drawSymbol(ctx, v, x, y, s, fill, lw) {
    ctx.save(); ctx.translate(x, y);
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    if (/^[0-9]$/.test(v) || v === 'D2' || v === 'W4') {
      const t = v === 'D2' ? '+2' : v === 'W4' ? '+4' : v;
      ctx.font = `${s}px ${FONT_D}`;
      strokeFillText(ctx, t, 0, s * 0.05, fill, INK, lw);
      if (v === '6' || v === '9') {
        const w = s * 0.34, h = s * 0.06, yy = s * 0.43;
        if (lw) { ctx.fillStyle = INK; ctx.fillRect(-w / 2 - lw / 2, yy - lw / 2, w + lw, h + lw); }
        ctx.fillStyle = fill; ctx.fillRect(-w / 2, yy, w, h);
      }
    } else if (v === 'S') {
      const r = s * 0.3, w = s * 0.13;
      const ring = (col, ex) => {
        ctx.strokeStyle = col; ctx.lineWidth = w + ex; ctx.lineCap = 'round';
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(-r * 0.68, r * 0.68); ctx.lineTo(r * 0.68, -r * 0.68); ctx.stroke();
      };
      if (lw) ring(INK, lw * 2);
      ring(fill, 0);
    } else if (v === 'R') {
      const w = s * 0.11, o = s * 0.1;
      arrow(ctx, -s * 0.3 - o, s * 0.2 - o, s * 0.12 - o, -s * 0.22 - o, w, fill, lw);
      arrow(ctx, s * 0.3 + o, -s * 0.2 + o, -s * 0.12 + o, s * 0.22 + o, w, fill, lw);
    } else if (v === 'W') {
      quadHex(ctx, 0, 0, s * 0.42, lw ? Math.max(3, lw * 0.7) : 0);
    }
    ctx.restore();
  }

  function drawBase(ctx, color) {
    ctx.clearRect(0, 0, CW, CH);
    ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0, 0, CW, CH);   // sem cantos transparentes (no 3D o canto é recortado pela geometria)
    rr(ctx, 14, 14, CW - 28, CH - 28, 20); ctx.fillStyle = color; ctx.fill();
  }

  function drawStandardCard(tk, target) {
    const cv = mkCanvas(target), ctx = cv.getContext('2d');
    const { c, v } = parseType(tk);
    const col = COLOR_HEX[c];
    drawBase(ctx, col);
    const cx = CW / 2, cy = CH / 2;
    if (c === 'k') {
      quadHex(ctx, cx, cy, 124, 10);
      if (v === 'W4') drawSymbol(ctx, 'W4', cx, cy, 128, '#FFFFFF', 16);
    } else {
      ctx.save(); ctx.translate(cx, cy); ctx.rotate(0.12);
      hexPath(ctx, 0, 0, 124); ctx.fillStyle = '#FFFFFF'; ctx.fill();
      ctx.restore();
      const size = /^[0-9]$/.test(v) ? 190 : v === 'D2' ? 150 : 210;
      drawSymbol(ctx, v, cx, cy, size, col, 14);
    }
    drawSymbol(ctx, v, 54, 64, 64, '#FFFFFF', 9);
    ctx.save(); ctx.translate(CW - 54, CH - 64); ctx.rotate(Math.PI);
    drawSymbol(ctx, v, 0, 0, 64, '#FFFFFF', 9);
    ctx.restore();
    return cv;
  }

  function drawPattern(ctx, p, x, y, w, h) {
    ctx.save();
    ctx.fillStyle = 'rgba(255,255,255,0.2)'; ctx.strokeStyle = 'rgba(255,255,255,0.2)';
    if (p === 'dots') {
      for (let yy = y, r = 0; yy < y + h; yy += 26, r++) for (let xx = x + (r % 2) * 13; xx < x + w; xx += 26) { ctx.beginPath(); ctx.arc(xx, yy, 5, 0, 7); ctx.fill(); }
    } else if (p === 'stripes') {
      ctx.lineWidth = 12;
      for (let k = -h; k < w + h; k += 34) { ctx.beginPath(); ctx.moveTo(x + k, y); ctx.lineTo(x + k - h, y + h); ctx.stroke(); }
    } else if (p === 'hex') {
      ctx.lineWidth = 3;
      for (let yy = y, r = 0; yy < y + h + 30; yy += 30, r++) for (let xx = x + (r % 2) * 26; xx < x + w + 30; xx += 52) { hexPath(ctx, xx, yy, 16); ctx.stroke(); }
    } else if (p === 'stars') {
      for (let yy = y + 14, r = 0; yy < y + h; yy += 44, r++) for (let xx = x + 14 + (r % 2) * 22; xx < x + w; xx += 44) {
        ctx.beginPath();
        for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, rad = i % 2 ? 4 : 10; ctx.lineTo(xx + rad * Math.cos(a), yy + rad * Math.sin(a)); }
        ctx.closePath(); ctx.fill();
      }
    } else if (p === 'waves') {
      ctx.lineWidth = 6;
      for (let yy = y; yy < y + h + 20; yy += 28) { ctx.beginPath(); for (let xx = x; xx <= x + w; xx += 6) ctx.lineTo(xx, yy + Math.sin(xx / 16) * 7); ctx.stroke(); }
    } else if (p === 'checks') {
      for (let yy = y, r = 0; yy < y + h; yy += 28, r++) for (let xx = x + (r % 2) * 28; xx < x + w; xx += 56) ctx.fillRect(xx, yy, 28, 28);
    }
    ctx.restore();
  }
  function wrapLines(ctx, text, maxW, maxLines) {
    const words = String(text || '').split(/\s+/).filter(Boolean);
    const lines = []; let line = '';
    for (const w of words) {
      const t = line ? line + ' ' + w : w;
      if (ctx.measureText(t).width > maxW && line) { lines.push(line); line = w; } else line = t;
      if (lines.length === maxLines) break;
    }
    if (lines.length < maxLines && line) lines.push(line);
    if (lines.length === maxLines && words.join(' ').length > lines.join(' ').length) {
      let l = lines[maxLines - 1];
      while (ctx.measureText(l + '…').width > maxW && l.length) l = l.slice(0, -1);
      lines[maxLines - 1] = l + '…';
    }
    return lines;
  }
  function fitText(ctx, text, maxW) {
    let t = String(text || '');
    if (ctx.measureText(t).width <= maxW) return t;
    while (t.length && ctx.measureText(t + '…').width > maxW) t = t.slice(0, -1);
    return t + '…';
  }

  // carta de inscrito: mantém a cor (moldura) e o valor (cantos) para o jogo continuar legível
  const clampN = (v, a, b) => Math.min(b, Math.max(a, isFinite(v) ? v : a));
  function drawSubCard(tk, rep, photoImg, target, bgImg) {
    const okImg = im => im && im.complete && im.naturalWidth;
    const cv = mkCanvas(target), ctx = cv.getContext('2d');
    const { c, v } = parseType(tk);
    const col = COLOR_HEX[c];
    drawBase(ctx, col);
    ctx.save();
    rr(ctx, 30, 30, CW - 60, CH - 60, 16); ctx.clip();
    const g = ctx.createLinearGradient(0, 30, 0, CH - 30);
    g.addColorStop(0, rep.a || '#FF6FB5'); g.addColorStop(1, rep.b || '#7B2FF7');
    ctx.fillStyle = g; ctx.fillRect(30, 30, CW - 60, CH - 60);
    drawPattern(ctx, rep.pattern, 30, 30, CW - 60, CH - 60);
    const hasBg = okImg(bgImg);
    if (hasBg) {          // imagem de fundo escolhida no ADM, em destaque
      const W = CW - 60, Hh = CH - 60, z = clampN(+rep.bgZ || 1, 1, 4);
      const sc = Math.max(W / bgImg.naturalWidth, Hh / bgImg.naturalHeight) * z;
      const w = bgImg.naturalWidth * sc, h = bgImg.naturalHeight * sc;
      // posição ajustada no ADM (-1 a 1 em cada eixo)
      const ox = clampN(+rep.bgX || 0, -1, 1) * (w - W) / 2, oy = clampN(+rep.bgY || 0, -1, 1) * (h - Hh) / 2;
      ctx.drawImage(bgImg, 30 + (W - w) / 2 - ox, 30 + (Hh - h) / 2 - oy, w, h);
      const sh = ctx.createLinearGradient(0, 250, 0, CH - 30);
      sh.addColorStop(0, 'rgba(16,32,43,0)'); sh.addColorStop(1, 'rgba(16,32,43,.7)');
      ctx.fillStyle = sh; ctx.fillRect(30, 250, W, CH - 280);
    }
    ctx.restore();
    rr(ctx, 30, 30, CW - 60, CH - 60, 16); ctx.lineWidth = 4; ctx.strokeStyle = '#FFFFFF'; ctx.stroke();

    // sem imagem de fundo: hexágono com o emoji no meio
    if (!hasBg) {
      const hx = CW / 2, hy = 196, hr = 92;
      hexPath(ctx, hx, hy, hr + 6); ctx.fillStyle = INK; ctx.fill();
      hexPath(ctx, hx, hy, hr); ctx.fillStyle = '#FFFFFF'; ctx.fill();
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.font = `104px ${FONT_E}`; ctx.fillStyle = INK;
      ctx.fillText(rep.emoji || '⭐', hx, hy + 6);
    }

    // comentário (2 linhas)
    ctx.font = `italic 800 19px ${FONT_B}`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    const lines = wrapLines(ctx, '“' + (rep.text || '') + '”', 236, 2);
    lines.forEach((l, i) => {
      ctx.fillStyle = 'rgba(16,32,43,0.55)'; ctx.fillText(l, CW / 2 + 1.5, 314 + i * 24 + 2);
      ctx.fillStyle = '#FFFFFF'; ctx.fillText(l, CW / 2, 314 + i * 24);
    });

    // faixa inferior: autor + atributo
    rr(ctx, 42, 368, CW - 84, 92, 16); ctx.fillStyle = 'rgba(16,32,43,0.82)'; ctx.fill();
    // foto da pessoa no canto da faixa
    const hasPh = okImg(photoImg), tx = hasPh ? CW / 2 + 36 : CW / 2, tw = hasPh ? CW - 180 : CW - 110;
    if (hasPh) {
      const px = 52, py = 378, ps = 72;
      rr(ctx, px - 3, py - 3, ps + 6, ps + 6, 14); ctx.fillStyle = '#FFFFFF'; ctx.fill();
      ctx.save(); rr(ctx, px, py, ps, ps, 11); ctx.clip();
      const sc = Math.max(ps / photoImg.naturalWidth, ps / photoImg.naturalHeight);
      ctx.drawImage(photoImg, px + (ps - photoImg.naturalWidth * sc) / 2, py + (ps - photoImg.naturalHeight * sc) / 2, photoImg.naturalWidth * sc, photoImg.naturalHeight * sc);
      ctx.restore();
    }
    ctx.textAlign = 'center';
    ctx.font = `27px ${FONT_D}`; ctx.fillStyle = '#FFFFFF';
    ctx.fillText(fitText(ctx, rep.author || '@inscrito', tw), tx, 398);
    const ef = EFFECTS[rep.effect];
    if (ef) {
      ctx.font = `900 17px ${FONT_B}`; ctx.fillStyle = '#8FF3FF';
      ctx.fillText(fitText(ctx, ef.name + ': ' + ef.desc, tw + 6), tx, 432);
    }

    // valor nos cantos (em medalhão da cor)
    const medal = (x, y, rot) => {
      ctx.save(); ctx.translate(x, y); ctx.rotate(rot);
      ctx.beginPath(); ctx.arc(0, 0, 38, 0, 7); ctx.fillStyle = INK; ctx.fill();
      ctx.beginPath(); ctx.arc(0, 0, 33, 0, 7); ctx.fillStyle = col; ctx.fill();
      drawSymbol(ctx, v, 0, 0, 52, '#FFFFFF', 7);
      ctx.restore();
    };
    medal(58, 64, 0);
    medal(CW - 58, CH - 64, Math.PI);
    // selo do atributo
    if (ef) {
      ctx.beginPath(); ctx.arc(CW - 60, 62, 28, 0, 7); ctx.fillStyle = '#FFFFFF'; ctx.fill();
      ctx.lineWidth = 5; ctx.strokeStyle = INK; ctx.stroke();
      ctx.font = `30px ${FONT_E}`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(ef.emoji, CW - 60, 64);
    }
    return cv;
  }

  function drawBack(target) {
    const cv = mkCanvas(target), ctx = cv.getContext('2d');
    drawBase(ctx, '#20C6DD');
    ctx.save(); rr(ctx, 14, 14, CW - 28, CH - 28, 20); ctx.clip();
    ctx.strokeStyle = 'rgba(16,32,43,0.12)'; ctx.lineWidth = 3;
    for (let yy = 0, r = 0; yy < CH + 30; yy += 30, r++) for (let xx = (r % 2) * 26; xx < CW + 30; xx += 52) { hexPath(ctx, xx, yy, 16); ctx.stroke(); }
    ctx.restore();
    hexPath(ctx, CW / 2, CH / 2, 116); ctx.fillStyle = '#FFFFFF'; ctx.fill();
    ctx.lineWidth = 12; ctx.strokeStyle = INK; ctx.stroke();
    ctx.save(); ctx.translate(CW / 2, CH / 2); ctx.rotate(-0.22);
    ctx.font = `92px ${FONT_D}`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.lineJoin = 'round';
    ctx.lineWidth = 22; ctx.strokeStyle = INK; ctx.strokeText('UNO', 0, 6);
    ctx.lineWidth = 12; ctx.strokeStyle = '#FFFFFF'; ctx.strokeText('UNO', 0, 6);
    ctx.fillStyle = '#1C6ED8'; ctx.fillText('UNO', 0, 6);
    ctx.restore();
    return cv;
  }

  /* ---------- 9. Armazenamento (Firebase ou local) ---------- */
  const LS_CONFIG = 'uno_config_v1';
  const LS_CMD = 'uno_cmd_v1';
  function firebaseConfigured() {
    return !!(global.firebase && FIREBASE_CONFIG.apiKey && FIREBASE_CONFIG.apiKey.indexOf('COLE') !== 0 && FIREBASE_CONFIG.databaseURL);
  }
  const Store = {
    mode: 'local', db: null,
    init() {
      if (firebaseConfigured()) {
        try {
          if (!global.firebase.apps.length) global.firebase.initializeApp(FIREBASE_CONFIG);
          this.db = global.firebase.database();
          this.mode = 'firebase';
        } catch (e) { console.error(e); this.mode = 'local'; }
      }
      return this.mode;
    },
    ref(p) { return this.db.ref(DB_ROOT + (p ? '/' + p : '')); },
    readLocal() { try { return JSON.parse(localStorage.getItem(LS_CONFIG) || 'null'); } catch (e) { return null; } },
    onConfig(cb) {
      if (this.mode === 'firebase') {
        this.ref('config').on('value', s => cb(fixConfig(s.val())));
      } else {
        cb(fixConfig(this.readLocal()));
        global.addEventListener('storage', e => { if (e.key === LS_CONFIG) cb(fixConfig(this.readLocal())); });
      }
    },
    saveConfig(cfg) {
      const data = { settings: cfg.settings, comments: cfg.comments, realV: cfg.realV || 7 };
      if (this.mode === 'firebase') return this.ref('config').set(clone(data));
      try { localStorage.setItem(LS_CONFIG, JSON.stringify(data)); return Promise.resolve(); }
      catch (e) { return Promise.reject(new Error('O navegador não tem espaço para salvar (fotos grandes demais?)')); }
    },
    saveVolumes(musicVol, sfxVol) {        // só os dois volumes: não mexe no resto da configuração
      if (this.mode === 'firebase') return this.ref('config/settings').update({ musicVol, sfxVol });
      const raw = this.readLocal(); if (!raw) return Promise.reject(new Error('sem configuração salva'));
      raw.settings = Object.assign({}, raw.settings, { musicVol, sfxVol });
      try { localStorage.setItem(LS_CONFIG, JSON.stringify(raw)); return Promise.resolve(); } catch (e) { return Promise.reject(e); }
    },
    resetConfig() {
      if (this.mode === 'firebase') return this.ref('config').remove();
      localStorage.removeItem(LS_CONFIG); return Promise.resolve();
    },

    /* ----- a sala única (sem código): usada pelo ADM e pelo jogo ----- */
    room() { return this.ref('rooms/' + ROOM); },
    async serverNow() {
      try { const o = await this.db.ref('.info/serverTimeOffset').get(); return Date.now() + (o.val() || 0); }
      catch (e) { return Date.now(); }
    },
    // começa (ou recomeça) a partida com quem está na sala: até 4, na ordem das cadeiras
    async startMatch(settings) {
      const ref = this.room();
      const [pSnap, mSnap] = await Promise.all([ref.child('players').get(), ref.child('meta').get()]);
      const P = pSnap.val() || {}, meta = mSnap.val() || {};
      const key = id => (P[id].seat >= 0 ? P[id].seat : 50) * 1e13 + (P[id].joinedAt || 0);
      const ids = Object.keys(P).filter(id => (P[id].bot || P[id].online !== false) && !P[id].out).sort((a, b) => key(a) - key(b));
      const order = ids.slice(0, 4);
      if (order.length < 2) throw new Error('Precisa de pelo menos 2 jogadores (ponha bots se quiser).');
      const humans = order.filter(id => !P[id].bot);
      if (!humans.length) throw new Error('Precisa de pelo menos 1 pessoa na sala (só bots não dá).');
      const up = {};
      order.forEach((id, i) => { up['players/' + id + '/seat'] = i; });
      ids.slice(4).forEach(id => { up['players/' + id + '/seat'] = -1; });
      Object.keys(P).forEach(id => { up['players/' + id + '/ready'] = null; up['players/' + id + '/again'] = null; });
      if (humans.indexOf(meta.host) < 0) up['meta/host'] = humans[0];
      const now = await this.serverNow();
      const subs = (await ref.child('subs').get()).val() || {};
      up.state = clone(newGame(order, now + 3600, settings, subs));
      up['meta/status'] = 'loading';
      up['meta/startAt'] = null;
      up['meta/round'] = (meta.round || 0) + 1;
      if (meta.rules) up.state.rules = Object.assign(up.state.rules, pickRules(Object.assign({}, settings, meta.rules)));
      const rd = {}; humans.forEach(id => rd[id] = true);    // já disseram "estou pronto" no lobby
      up['meta/ready'] = rd;
      up.actions = null; up.cmd = null;
      await ref.update(up);
    },
    async toLobby() {
      const ref = this.room();
      const P = (await ref.child('players').get()).val() || {};
      const up = { 'meta/status': 'lobby', 'meta/ready': null, 'meta/startAt': null, state: null, actions: null, cmd: null };
      Object.keys(P).forEach(id => { up['players/' + id + '/ready'] = null; });
      await ref.update(up);
    },
    async addBot() {
      const used = [];
      const res = await this.room().child('players').transaction(cur => {
        cur = cur || {};
        const taken = new Set(Object.values(cur).map(p => p.seat));
        let seat = -1; for (let i = 0; i < 4; i++) if (!taken.has(i)) { seat = i; break; }
        if (seat < 0) return;
        Object.values(cur).forEach(p => p.bot && used.push(p.name));
        const name = BOT_NAMES.find(n => used.indexOf(n) < 0) || 'Robô';
        cur['bot' + Math.random().toString(36).slice(2, 8)] = { name, photo: '', bot: true, online: true, seat, joinedAt: Date.now() };
        return cur;
      });
      if (!res.committed) throw new Error('As 4 cadeiras já estão ocupadas.');
    },
    replaceWithBot(id) {
      return this.room().child('players/' + id).transaction(p => {
        if (!p) return;
        return Object.assign(p, { bot: true, online: true, afk: null, ready: true, name: (p.name || 'Jogador') + ' 🤖' });
      });
    },
    debugSubsData(n, comments) {           // monta N cartas de inscritos já reveladas (para testar)
      const list = shuffle(activeComments(comments)), types = shuffle(TYPE_KEYS.slice()), replaced = {}, used = [], rep = [];
      n = Math.min(n, types.length);
      for (let i = 0; i < n && list.length; i++) {
        let c;
        if (i < list.length) { c = list[i]; used.push(c.id); }
        else { let pool = list.filter(x => rep.indexOf(x.id) < 0); if (!pool.length) { rep.length = 0; pool = list; } c = pool[rnd(pool.length)]; rep.push(c.id); }
        replaced[types[i]] = commentSnapshot(c);
      }
      return { replaced, used, rep, repMode: n > list.length };
    },
    async debugSubs(n, comments) {
      const d = this.debugSubsData(n, comments);
      if (this.mode === 'firebase') { await this.room().child('subs').set(clone(d)); await this.room().child('cmd').set({ type: 'debugSubs', t: Date.now() }); }
      else { localStorage.setItem('uno_subs', JSON.stringify(d)); localStorage.setItem('uno_cmd_v1', JSON.stringify({ type: 'debugSubs', t: Date.now() })); }
    },
    kick(id) { return this.room().child('players/' + id).remove(); },   // apaga tudo da pessoa (pontos inclusive)
    saveSubs(replaced, used, rep) {
      const v = { replaced: replaced || {}, used: used || [], rep: rep || [] };
      if (this.mode === 'firebase') return this.room().child('subs').set(clone(v));
      try { localStorage.setItem('uno_subs', JSON.stringify(v)); } catch (e) {}
      return Promise.resolve();
    },
    loadSubsLocal() { try { return JSON.parse(localStorage.getItem('uno_subs') || 'null') || {}; } catch (e) { return {}; } },
    resetSubs() {
      if (this.mode === 'firebase') return this.room().child('subs').remove();
      localStorage.removeItem('uno_subs'); localStorage.setItem('uno_cmd_v1', JSON.stringify({ type: 'resetSubs', t: Date.now() }));
      return Promise.resolve();
    },
    resetScores() {
      if (this.mode !== 'firebase') { localStorage.setItem('uno_cmd_v1', JSON.stringify({ type: 'resetScores', t: Date.now() })); return Promise.resolve(); }
      return this.room().child('players').get().then(sn => { const up = {}; Object.keys(sn.val() || {}).forEach(id => up[id + '/score'] = null); return this.room().child('players').update(up); });
    },

    /* ----- músicas (mp3 enviados no ADM): ficam separadas da config para não pesar ----- */
    idb() {
      return this._idb || (this._idb = new Promise((res, rej) => {
        const r = indexedDB.open('uno_music', 1);
        r.onupgradeneeded = () => r.result.createObjectStore('m');
        r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
      }));
    },
    async saveMusic(kind, dataUrl) {
      if (this.mode === 'firebase') return this.ref('music/' + kind).set(dataUrl || null);
      const db = await this.idb();
      await new Promise((res, rej) => { const tx = db.transaction('m', 'readwrite'); const st = tx.objectStore('m'); dataUrl ? st.put(dataUrl, kind) : st.delete(kind); tx.oncomplete = res; tx.onerror = () => rej(tx.error); });
      localStorage.setItem('uno_music_ping', kind + ':' + Date.now());
    },
    getMusicOnce(kind) {
      if (this.mode === 'firebase') return this.ref('music/' + kind).get().then(s => s.val() || null);
      return this.idb().then(db => new Promise(res => { const r = db.transaction('m').objectStore('m').get(kind); r.onsuccess = () => res(r.result || null); r.onerror = () => res(null); })).catch(() => null);
    },
    onMusic(cb) {
      const kinds = ['bg', 'uno', 'voice', 'clap', 'catch', 'key', 'dark'];
      if (this.mode === 'firebase') { kinds.forEach(k => this.ref('music/' + k).on('value', s => cb(k, s.val() || null))); return; }
      const load = async k => {
        try {
          const db = await this.idb();
          const v = await new Promise(res => { const r = db.transaction('m').objectStore('m').get(k); r.onsuccess = () => res(r.result || null); r.onerror = () => res(null); });
          cb(k, v);
        } catch (e) { cb(k, null); }
      };
      kinds.forEach(load);
      global.addEventListener('storage', e => { if (e.key === 'uno_music_ping' && e.newValue) load(e.newValue.split(':')[0]); });
    },
    command(type) { return this.room().child('cmd').set({ type, t: Date.now() }); }
  };
  const ROOM = 'principal';
  const BOT_NAMES = ['Robô Hexa', 'Robô Ciano', 'Robô Pixel', 'Robô Bolha'];

  // redimensiona uma foto enviada para um quadrado pequeno (dataURL leve)
  function resizeImageFile(file, size) {
    size = size || 128;
    return new Promise((res, rej) => {
      const fr = new FileReader();
      fr.onerror = () => rej(new Error('Não foi possível ler a imagem'));
      fr.onload = () => {
        const img = new Image();
        img.onerror = () => rej(new Error('Arquivo de imagem inválido'));
        img.onload = () => {
          const c = document.createElement('canvas'); c.width = c.height = size;
          const x = c.getContext('2d');
          const s = Math.max(size / img.width, size / img.height);
          x.drawImage(img, (size - img.width * s) / 2, (size - img.height * s) / 2, img.width * s, img.height * s);
          res(c.toDataURL('image/jpeg', 0.82));
        };
        img.src = fr.result;
      };
      fr.readAsDataURL(file);
    });
  }

